1	import fs from 'fs';
2	import path from 'path';
3	import { parseFrontmatter, Frontmatter } from './frontmatter';
4	import { markdownToHtml } from './markdown';
5	import { TemplateEngine } from './templates';
6	
7	export interface PageData {
8	  slug: string;
9	  filename: string;
10	  frontmatter: Frontmatter;
11	  content: string;
12	  html: string;
13	}
14	
15	export async function readMarkdownFiles(contentDir: string): Promise<string[]> {
16	  if (!fs.existsSync(contentDir)) {
17	    throw new Error(`Content directory not found: ${contentDir}`);
18	  }
19	
20	  const files = fs.readdirSync(contentDir);
21	  return files.filter((file) => file.endsWith('.md'));
22	}
23	
24	export async function parseMarkdownFile(
25	  filePath: string
26	): Promise<PageData> {
27	  const content = fs.readFileSync(filePath, 'utf-8');
28	  const { frontmatter, content: markdown } = parseFrontmatter(content);
29	  const html = markdownToHtml(markdown);
30	  const filename = path.basename(filePath);
31	  const slug = filename.replace(/\.md$/, '');
32	
33	  return {
34	    slug,
35	    filename,
36	    frontmatter,
37	    content: markdown,
38	    html,
39	  };
40	}
41	
42	export async function generatePages(
43	  contentDir: string,
44	  outputDir: string,
45	  templateEngine?: TemplateEngine
46	): Promise<PageData[]> {
47	  if (!fs.existsSync(outputDir)) {
48	    fs.mkdirSync(outputDir, { recursive: true });
49	  }
50	
51	  const files = await readMarkdownFiles(contentDir);
52	  const pages: PageData[] = [];
53	
54	  for (const file of files) {
55	    const filePath = path.join(contentDir, file);
56	    const pageData = await parseMarkdownFile(filePath);
57	    pages.push(pageData);
58	
59	    const outputPath = path.join(outputDir, `${pageData.slug}.html`);
60	    const html = templateEngine
61	      ? generatePageHtmlWithTemplate(pageData, templateEngine)
62	      : generatePageHtml(pageData);
63	    fs.writeFileSync(outputPath, html, 'utf-8');
64	  }
65	
66	  return pages;
67	}
