69	export function generatePageHtml(page: PageData): string {
70	  const title = page.frontmatter.title || page.slug;
71	  const date = page.frontmatter.date ? `<p class="date">${page.frontmatter.date}</p>` : '';
72	  const tags =
73	    page.frontmatter.tags && Array.isArray(page.frontmatter.tags)
74	      ? `<div class="tags">${page.frontmatter.tags
75	          .map((tag) => `<span class="tag">${escapeHtml(String(tag))}</span>`)
76	          .join('')}</div>`
77	      : '';
78	
79	  return `<!DOCTYPE html>
80	<html lang="en">
81	<head>
82	  <meta charset="UTF-8">
83	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
84	  <title>${escapeHtml(title)}</title>
85	  <style>
86	    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; line-height: 1.6; }
87	    h1, h2, h3 { margin-top: 1.5em; }
88	    .date { color: #666; font-size: 0.9em; }
89	    .tags { margin: 10px 0; }
90	    .tag { display: inline-block; background: #f0f0f0; padding: 4px 8px; margin: 4px 4px 4px 0; border-radius: 4px; font-size: 0.85em; }
91	    a { color: #0066cc; }
92	  </style>
93	</head>
94	<body>
95	  <a href="index.html">← Back to Index</a>
96	  <article>
97	    <h1>${escapeHtml(title)}</h1>
98	    ${date}
99	    ${tags}
100	    <div class="content">
101	      ${page.html}
102	    </div>
103	  </article>
104	</body>
105	</html>`;
106	}
107	
108	export function generateIndexHtml(pages: PageData[]): string {
109	  const sortedPages = pages.sort((a, b) => {
110	    const dateA = new Date(String(a.frontmatter.date) || 0).getTime();
111	    const dateB = new Date(String(b.frontmatter.date) || 0).getTime();
112	    return dateB - dateA;
113	  });
114	
115	  const pagesList = sortedPages
116	    .map((page) => {
117	      const title = page.frontmatter.title || page.slug;
118	      const date = page.frontmatter.date ? ` — ${page.frontmatter.date}` : '';
119	      return `<li><a href="${page.slug}.html">${escapeHtml(title)}</a>${date}</li>`;
120	    })
121	    .join('\n    ');
122	
123	  return `<!DOCTYPE html>
124	<html lang="en">
125	<head>
126	  <meta charset="UTF-8">
127	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
128	  <title>Site Index</title>
129	  <style>
130	    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; line-height: 1.6; }
131	    h1 { margin-bottom: 1.5em; }
132	    ul { list-style: none; padding: 0; }
133	    li { margin: 12px 0; }
134	    a { color: #0066cc; text-decoration: none; }
135	    a:hover { text-decoration: underline; }
136	  </style>
137	</head>
138	<body>
139	  <h1>Site Index</h1>
140	  <ul>
141	    ${pagesList}
142	  </ul>
143	</body>
144	</html>`;
145	}
146	
147	export function generatePageHtmlWithTemplate(
148	  page: PageData,
149	  templateEngine: TemplateEngine
150	): string {
151	  const templateName = String(page.frontmatter.template || 'page');
152	  const layoutName = String(page.frontmatter.layout || 'default');
153	
154	  const context = {
155	    title: page.frontmatter.title || page.slug,
156	    slug: page.slug,
157	    filename: page.filename,
158	    date: page.frontmatter.date,
159	    tags: page.frontmatter.tags,
160	    content: page.html,
161	    ...page.frontmatter,
162	  };
163	
164	  const templateContent = templateEngine.renderTemplate(templateName, context);
165	
166	  if (templateEngine.hasLayout(layoutName)) {
167	    return templateEngine.renderPageWithLayout(templateContent, layoutName, context);
168	  }
169	
170	  return templateContent;
171	}
172	
173	export async function build(
174	  contentDir: string = './content',
175	  outputDir: string = './dist',
176	  templatesDir: string = './templates'
177	): Promise<void> {
178	  if (!fs.existsSync(outputDir)) {
179	    fs.mkdirSync(outputDir, { recursive: true });
180	  }
181	
182	  let templateEngine: TemplateEngine | undefined;
183	  if (fs.existsSync(templatesDir)) {
184	    templateEngine = new TemplateEngine({
185	      templatesDir,
186	      layoutsDir: path.join(templatesDir, 'layouts'),
187	      partialsDir: path.join(templatesDir, 'partials'),
188	    });
189	  }
190	
191	  const pages = await generatePages(contentDir, outputDir, templateEngine);
192	  const indexHtml = generateIndexHtml(pages);
193	  fs.writeFileSync(path.join(outputDir, 'index.html'), indexHtml, 'utf-8');
194	}
195	
196	function escapeHtml(text: string): string {
197	  const escapeMap: { [key: string]: string } = {
198	    '&': '&amp;',
199	    '<': '&lt;',
200	    '>': '&gt;',
201	    '"': '&quot;',
202	    "'": '&#39;',
203	  };
204	  return text.replace(/[&<>"']/g, (char) => escapeMap[char]);
205	}
